1	/**
2	 * Washer-world materials: procedural perforated magenta metal (round holes for drums, circumferential
3	 * slots for tunnels), thick reflective gold, chrome, glass — all PBR (MeshStandardMaterial) so they pick
4	 * up the candy PMREM environment, with shader patches for the perforations and glow.
5	 */
6	import * as THREE from 'three';
7	
8	export interface PerforatedOptions {
9	  /** base metal colour */
10	  color?: THREE.ColorRepresentation;
11	  /** colour of the hole interiors */
12	  holeColor?: THREE.ColorRepresentation;
13	  /** 0 = round holes (drum), 1 = slots elongated along u (tunnel rings) */
14	  slot?: number;
15	  /** pattern repeats: holes around u (per 0..1) and per uv-unit along v */
16	  repeatU?: number;
17	  repeatV?: number;
18	  /** hole size relative to its cell (0..1) */
19	  holeSize?: number;
20	  emissive?: THREE.ColorRepresentation;
21	  emissiveIntensity?: number;
22	  metalness?: number;
23	  roughness?: number;
24	  side?: THREE.Side;
25	  /** bright stripe highlights running along v (tunnel light streaks) */
26	  streaks?: number;
27	  /** number of procedural lengthwise streaks around u (default 9) */
28	  streakCount?: number;
29	  /**
30	   * explicit slot half-size in CELL units [along u, along v] (overrides holeSize/slot); the cell is
31	   * 1/repeatU of the circumference by 1/repeatV along the tube, so world proportions follow from both
32	   */
33	  slotHalf?: [number, number];
34	  /** stagger every other slot row by half a cell (default true) */
35	  stagger?: boolean;
36	  /**
37	   * Washer-tube upgrade (05–07): pressed-metal corrugation + bevelled slot lips perturb the normal so
38	   * the glossy metal catches light around every slot (refs 05–07). Height amplitudes in world units.
39	   */
40	  relief?: { corrugation: number; bevel: number; bevelWidth?: number };
41	  /** emissive glow colour hugging every hole edge (refs: hot-pink glowing slot outlines) */
42	  rimColor?: THREE.ColorRepresentation;
43	  rimStrength?: number;
44	  /** warm "light at the end of the tunnel": emissive that grows with view distance */
45	  farGlow?: FarGlow;
46	  /** dedicated reflection environment (e.g. washerTubeEnv()) instead of scene.environment */
47	  envMap?: THREE.Texture | null;
48	  envMapIntensity?: number;
49	}
50	
51	export interface FarGlow {
52	  color: THREE.ColorRepresentation; near: number; far: number; strength: number;
53	  /** optional mid-distance tint of the metal colour (refs: walls turn violet deeper in the tunnel) */
54	  mid?: { color: THREE.ColorRepresentation; near: number; far: number; amount: number };
55	}
56	
57	/** GLSL for the distance glow, shared by the tube wall, rings and lids */
58	const FAR_GLOW_PARS = `uniform vec3 uFarGlowColor; uniform vec3 uFarGlowRange; uniform vec3 uMidTint; uniform vec3 uMidRange;
59	float farGlowK(){ return uFarGlowRange.z * smoothstep(uFarGlowRange.x, uFarGlowRange.y, length(vViewPosition)); }
60	float midTintK(){ return uMidRange.z * smoothstep(uMidRange.x, uMidRange.y, length(vViewPosition)); }`;
61	/** `solid` = 0 inside perforation holes (they stay dark), 1 on metal */
62	const FAR_GLOW_APPLY = (solid = '1.0') => `{ float sol = ${solid}; float mt = midTintK() * sol; diffuseColor.rgb = mix(diffuseColor.rgb, uMidTint, mt); totalEmissiveRadiance *= 1.0 - mt * 0.5;
63	  float fg = farGlowK(); diffuseColor.rgb = mix(diffuseColor.rgb, uFarGlowColor, min(1.0, fg * 0.5) * sol); totalEmissiveRadiance += uFarGlowColor * fg * mix(0.35, 1.0, sol); }`;
64	
65	function farGlowUniforms(g: FarGlow) {
66	  return {
67	    uFarGlowColor: { value: new THREE.Color(g.color) },
68	    uFarGlowRange: { value: new THREE.Vector3(g.near, g.far, g.strength) },
69	    uMidTint: { value: new THREE.Color(g.mid?.color ?? '#ffffff') },
70	    uMidRange: { value: new THREE.Vector3(g.mid?.near ?? 0, g.mid?.far ?? 1, g.mid?.amount ?? 0) },
71	  };
72	}
