74	/**
75	 * Adds the warm distance glow to any MeshStandardMaterial (rings, lids). The far end of the tube melts
76	 * into a bright warm vanishing point like refs 05/07 without adding scene lights (mobile-friendly).
77	 */
78	export function withFarGlow<T extends THREE.MeshStandardMaterial>(mat: T, g: FarGlow, key: string): T {
79	  const uniforms = farGlowUniforms(g);
80	  const prev = mat.onBeforeCompile;
81	  mat.onBeforeCompile = (shader, r) => {
82	    prev.call(mat, shader, r);
83	    Object.assign(shader.uniforms, uniforms);
84	    shader.fragmentShader = shader.fragmentShader
85	      .replace('#include <common>', '#include <common>\n' + FAR_GLOW_PARS)
86	      .replace(
87	        '#include <emissivemap_fragment>',
88	        `#include <emissivemap_fragment>
89	${FAR_GLOW_APPLY()}`,
90	      );
91	  };
92	  const prevKey = mat.customProgramCacheKey.bind(mat);
93	  mat.customProgramCacheKey = () => prevKey() + '|fg-' + key;
94	  mat.userData.farGlow = uniforms;
95	  return mat;
96	}
