98	/**
99	 * Analytic strip lights for the washer tubes (refs 05–07). Narrow light strips run the full length of
100	 * the tunnel at evenly spaced angles around its axis. Their radiance depends only on the azimuth of the
101	 * reflected view ray around the LOCAL tube axis, so (unlike a cube map, whose meridians pinch together
102	 * and blur at the pole every grazing wall reflection looks into) they stay crisp at any distance and
103	 * follow the tube through the 06 arch and the 07 plunge. The term is added to the IBL radiance, so the
104	 * normal PBR BRDF weights it: glossy magenta panels get lengthwise white-pink streaks, every gold band
105	 * gets evenly spaced "marquee" spots, and both line up radially like in the reference.
106	 * Axis source: 'attribute' = per-vertex `tubeAxis`/`tubeUp` (buildTubeGeometry({ axisAttr: true })),
107	 * 'instance' = local Z (axis) / local Y (up) of each instance matrix (rings, lids).
108	 */
109	export interface TubeStrips {
110	  count: number;
111	  /** angular half-width of one strip (radians, before roughness widening) */
112	  width: number;
113	  intensity: number;
114	  color: THREE.ColorRepresentation;
115	  /** brightness of every other strip (default 0.7) */
116	  alt?: number;
117	}
118	
119	export function withTubeStrips<T extends THREE.MeshStandardMaterial>(mat: T, s: TubeStrips, source: 'attribute' | 'instance', key: string): T {
120	  const uniforms = {
121	    uStripColor: { value: new THREE.Color(s.color).multiplyScalar(s.intensity) },
122	    uStripP: { value: new THREE.Vector4(s.count, s.width, 0, s.alt ?? 0.7) },
123	  };
124	  const prev = mat.onBeforeCompile;
125	  mat.onBeforeCompile = (shader, r) => {
126	    prev.call(mat, shader, r);
127	    Object.assign(shader.uniforms, uniforms);
128	    const axis = source === 'instance'
129	      ? `vTubeAxis = normalize((viewMatrix * modelMatrix * instanceMatrix * vec4(0.0, 0.0, 1.0, 0.0)).xyz);
130	vTubeUp = normalize((viewMatrix * modelMatrix * instanceMatrix * vec4(0.0, 1.0, 0.0, 0.0)).xyz);`
131	      : `vTubeAxis = normalize((viewMatrix * modelMatrix * vec4(tubeAxis, 0.0)).xyz);
132	vTubeUp = normalize((viewMatrix * modelMatrix * vec4(tubeUp, 0.0)).xyz);`;
133	    shader.vertexShader = shader.vertexShader
134	      .replace('#include <common>', `#include <common>
135	varying vec3 vTubeAxis; varying vec3 vTubeUp;
136	${source === 'attribute' ? 'attribute vec3 tubeAxis; attribute vec3 tubeUp;' : ''}`)
137	      .replace('#include <project_vertex>', `#include <project_vertex>
138	${axis}`);
139	    shader.fragmentShader = shader.fragmentShader
140	      .replace('#include <common>', `#include <common>
141	varying vec3 vTubeAxis; varying vec3 vTubeUp; uniform vec3 uStripColor; uniform vec4 uStripP;
142	vec3 tubeStripRadiance(vec3 V, vec3 N, float rough){
143	  vec3 R = reflect(-V, N);
144	  vec3 A = normalize(vTubeAxis);
145	  vec3 E1 = normalize(vTubeUp - A * dot(vTubeUp, A));
146	  vec3 E2 = cross(A, E1);
147	  vec3 P = R - A * dot(R, A);
148	  float pl = length(P);
149	  float t = atan(dot(P, E2), dot(P, E1)) * uStripP.x / 6.2831853; // strip index space
150	  float fw = min(fwidth(t), fwidth(fract(t + 0.5)));
151	  float w0 = uStripP.y * uStripP.x / 6.2831853;            // half-width in pitch units
152	  float w = w0 + rough * rough * 1.5 + fw * 0.6;
153	  float dA = fract(t + 0.5) - 0.5;
154	  float k = exp(-dA * dA / (w * w)) * mix(1.0, w0 / w, 0.75);
155	  k *= mod(floor(t + 0.5), 2.0) > 0.5 ? uStripP.w : 1.0;
156	  return uStripColor * k * smoothstep(0.02, 0.12, pl);
157	}`)
158	      .replace('#include <lights_fragment_maps>', `#include <lights_fragment_maps>
159	#if defined( RE_IndirectSpecular )
160	radiance += tubeStripRadiance(geometryViewDir, geometryNormal, material.roughness);
161	#endif`);
162	  };
163	  const prevKey = mat.customProgramCacheKey.bind(mat);
164	  mat.customProgramCacheKey = () => prevKey() + '|strips-' + source + '-' + key;
165	  mat.userData.tubeStrips = uniforms;
166	  return mat;
167	}
