169	export function perforatedMetal(o: PerforatedOptions = {}): THREE.MeshStandardMaterial {
170	  const mat = new THREE.MeshStandardMaterial({
171	    color: o.color ?? '#d13fd6',
172	    metalness: o.metalness ?? 0.72,
173	    roughness: o.roughness ?? 0.26,
174	    emissive: new THREE.Color(o.emissive ?? '#9a1fa8'),
175	    emissiveIntensity: o.emissiveIntensity ?? 0.26,
176	    side: o.side ?? THREE.BackSide,
177	    envMapIntensity: o.envMapIntensity ?? 1.0,
178	  });
179	  if (o.envMap) mat.envMap = o.envMap;
180	  const relief = o.relief;
181	  const uniforms = {
182	    uHoleColor: { value: new THREE.Color(o.holeColor ?? '#2b0640') },
183	    uSlot: { value: o.slot ?? 1 },
184	    uRepeat: { value: new THREE.Vector2(o.repeatU ?? 64, o.repeatV ?? 1.2) },
185	    uHoleSize: { value: o.holeSize ?? 0.42 },
186	    uStreaks: { value: o.streaks ?? 0.35 },
187	    uStreakN: { value: o.streakCount ?? 9 },
188	    uSlotHalf: { value: new THREE.Vector2(o.slotHalf?.[0] ?? -1, o.slotHalf?.[1] ?? -1) },
189	    uStagger: { value: o.stagger === false ? 0 : 0.5 },
190	    uRelief: { value: new THREE.Vector3(relief?.corrugation ?? 0, relief?.bevel ?? 0, relief?.bevelWidth ?? 0.09) },
191	    uRimColor: { value: new THREE.Color(o.rimColor ?? '#ffd1ff') },
192	    uRimStrength: { value: o.rimStrength ?? 0.55 },
193	    ...(o.farGlow ? farGlowUniforms(o.farGlow) : {}),
194	  };
195	  const defines: Record<string, string> = {};
196	  if (relief) defines.PERF_RELIEF = '';
197	  if (o.farGlow) defines.PERF_FARGLOW = '';
198	  mat.defines = defines;
199	  mat.userData.perfUniforms = uniforms;
200	  mat.onBeforeCompile = (shader) => {
201	    Object.assign(shader.uniforms, uniforms);
202	    shader.vertexShader = shader.vertexShader
203	      .replace('#include <common>', '#include <common>\nvarying vec2 vPerfUv;')
204	      .replace('#include <uv_vertex>', '#include <uv_vertex>\nvPerfUv = uv;');
205	    shader.fragmentShader = shader.fragmentShader
206	      .replace(
207	        '#include <common>',
208	        `#include <common>
209	varying vec2 vPerfUv;
210	uniform vec3 uHoleColor; uniform float uSlot; uniform vec2 uRepeat; uniform float uHoleSize; uniform float uStreaks;
211	uniform vec3 uRelief; uniform vec3 uRimColor; uniform float uRimStrength; uniform float uStreakN; uniform vec2 uSlotHalf; uniform float uStagger;
212	#ifdef PERF_FARGLOW
213	${FAR_GLOW_PARS}
214	#endif
215	vec2 perfCell(vec2 uv){
216	  vec2 g = uv * uRepeat;
217	  g.x += mod(floor(g.y), 2.0) * uStagger;   // staggered rows
218	  return g;
219	}
220	// signed distance to the slot/hole (cell units, <0 inside)
221	float perfSdf(vec2 g){
222	  vec2 f = fract(g) - 0.5;
223	  vec2 hs = uSlotHalf.x > 0.0 ? uSlotHalf : mix(vec2(uHoleSize*0.5), vec2(uHoleSize*0.62, uHoleSize*0.24), uSlot);
224	  vec2 q = abs(f) - hs + min(hs.x, hs.y);
225	  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - min(hs.x, hs.y);
226	}
227	float perfMask(vec2 uv, out float rim){
228	  vec2 g = perfCell(uv);
229	  vec2 f = fract(g) - 0.5;
230	  float d = perfSdf(g);
231	  float aa = fwidth(d) * 1.2 + 1e-4;
232	  rim = smoothstep(0.06, 0.0, abs(d - 0.02)) * step(0.0, f.y);  // light catching the lower lip
233	  return 1.0 - smoothstep(-aa, aa, d); // 1 inside hole
234	}
235	#ifdef PERF_RELIEF
236	// pressed-metal relief (world units): shallow grooves along each slot row, bevelled lips into every slot
237	float perfHeight(vec2 g){
238	  float fy = fract(g.y) - 0.5;
239	  float d = perfSdf(g);
240	  return -cos(6.2831853 * fy) * uRelief.x + (smoothstep(0.0, uRelief.z, d) - 1.0) * uRelief.y;
241	}
242	#endif`,
243	      )
244	      .replace(
245	        '#include <color_fragment>',
246	        `#include <color_fragment>
247	float perfRim; float perfHole = perfMask(vPerfUv, perfRim);
248	float streak = pow(0.5 + 0.5 * sin(vPerfUv.x * 6.2831 * uStreakN + 1.3), 18.0) * uStreaks;
249	diffuseColor.rgb = mix(diffuseColor.rgb * (1.0 + streak), uHoleColor, perfHole);`,
250	      )
251	      .replace(
252	        '#include <normal_fragment_maps>',
253	        `#include <normal_fragment_maps>
254	#ifdef PERF_RELIEF
255	{
256	  // analytic relief gradient in uv space → view space via the screen-derivative cotangent frame
257	  vec2 g = perfCell(vPerfUv);
258	  float e = 0.015;
259	  float h0 = perfHeight(g);
260	  vec2 dHdg = vec2(perfHeight(g + vec2(e, 0.0)) - h0, perfHeight(g + vec2(0.0, e)) - h0) / e;
261	  vec2 dHduv = dHdg * uRepeat;
262	  vec3 dp1 = dFdx(-vViewPosition), dp2 = dFdy(-vViewPosition);
263	  vec2 duv1 = dFdx(vPerfUv), duv2 = dFdy(vPerfUv);
264	  vec3 dp2perp = cross(dp2, normal), dp1perp = cross(normal, dp1);
265	  float det = dot(dp1, dp2perp);
266	  if (abs(det) > 1e-12) {
267	    vec3 gradU = (dp2perp * duv1.x + dp1perp * duv2.x) / det;
268	    vec3 gradV = (dp2perp * duv1.y + dp1perp * duv2.y) / det;
269	    // fade the relief out where the pattern gets sub-pixel (prevents sparkle in the distance)
270	    float px = max(length(fwidth(g)), 1e-4);
271	    float lod = 1.0 - smoothstep(0.18, 0.45, px);
272	    normal = normalize(normal - (dHduv.x * gradU + dHduv.y * gradV) * lod);
273	  }
274	}
275	#endif`,
276	      )
277	      .replace(
278	        '#include <metalnessmap_fragment>',
279	        `#include <metalnessmap_fragment>
280	metalnessFactor *= (1.0 - perfHole);`,
281	      )
282	      .replace(
283	        '#include <roughnessmap_fragment>',
284	        `#include <roughnessmap_fragment>
285	roughnessFactor = mix(roughnessFactor, 0.9, perfHole);`,
286	      )
287	      .replace(
288	        '#include <emissivemap_fragment>',
289	        `#include <emissivemap_fragment>
290	totalEmissiveRadiance = totalEmissiveRadiance * (1.0 - perfHole) + uRimColor * perfRim * uRimStrength * (1.0 - perfHole) + vec3(1.0,0.9,1.0) * streak * 0.6;
291	#ifdef PERF_FARGLOW
292	${FAR_GLOW_APPLY('1.0 - perfHole')}
293	#endif`,
294	      );
295	  };
296	  mat.customProgramCacheKey = () => 'perf-v3' + (relief ? '-r' : '') + (o.farGlow ? '-g' : '');
297	  return mat;
298	}
