300	/**
301	 * Reflection environment for the washer tubes (05–07): an HDR cube of hot-pink / magenta / violet with
302	 * pink-white strip lights around the tube and a warm gold-white glow down the tunnel (-Z), so the glossy
303	 * walls read rich saturated magenta (the shared candy studio has a cyan panel that turned them sky-blue).
304	 * Built from half-float DataTextures; three converts it to PMREM on first use (no renderer needed here).
305	 */
306	const tubeEnvs: Partial<Record<'wall' | 'gold', THREE.CubeTexture>> = {};
307	/** variant 'gold': same tunnel lighting seen by polished gold (warm-white strips, amber base) so rings and
308	 *  lids read clean orange-gold with yellow-white highlights instead of salmon (gold × magenta). */
309	export function washerTubeEnv(variant: 'wall' | 'gold' = 'wall'): THREE.CubeTexture {
310	  const cached = tubeEnvs[variant];
311	  if (cached) return cached;
312	  const isGold = variant === 'gold';
313	  const N = 128;
314	  const dir = new THREE.Vector3();
315	  const col = new THREE.Color();
316	  const faces: THREE.DataTexture[] = [];
317	  // cube face orientation (same convention as WebGL cube maps)
318	  const faceDir = (f: number, a: number, b: number) => {
319	    switch (f) {
320	      case 0: return dir.set(1, -b, -a);
321	      case 1: return dir.set(-1, -b, a);
322	      case 2: return dir.set(a, 1, b);
323	      case 3: return dir.set(a, -1, -b);
324	      case 4: return dir.set(a, -b, 1);
325	      default: return dir.set(-a, -b, -1);
326	    }
327	  };
328	  // Smooth base only: the strip lights are analytic (withTubeStrips), because grazing wall reflections all
329	  // look almost straight down the tunnel, where a cube map's meridian strips pinch together and blur.
330	  const cBaseTop = isGold ? new THREE.Color(0.62, 0.24, 0.07) : new THREE.Color(0.62, 0.05, 0.42);
331	  const cBaseLow = isGold ? new THREE.Color(0.3, 0.09, 0.05) : new THREE.Color(0.22, 0.05, 0.55);
332	  const radiance = (d: THREE.Vector3, out: THREE.Color) => {
333	    const up = d.y;
334	    // base: magenta above, violet toward the floor
335	    out.copy(cBaseTop).lerp(cBaseLow, THREE.MathUtils.smoothstep(-up, -0.3, 0.9));
336	    // gold only: a warm yellow-white core at the very end of the tunnel (-Z) so far bands glow like the VP
337	    const ahead = Math.max(0, -d.z);
338	    if (isGold) {
339	      const hot = Math.pow(ahead, 60), wide = Math.pow(ahead, 6);
340	      out.r += 2.4 * hot + 0.3 * wide; out.g += 2.0 * hot + 0.16 * wide; out.b += 1.0 * hot + 0.04 * wide;
341	    } else {
342	      const wide = Math.pow(ahead, 6);
343	      out.r += 0.05 * wide; out.g += 0.02 * wide; out.b += 0.25 * wide; // violet haze down the tunnel
344	    }
345	    return out;
346	  };
347	  for (let f = 0; f < 6; f++) {
348	    const data = new Uint16Array(N * N * 4);
349	    for (let y = 0; y < N; y++) {
350	      for (let x = 0; x < N; x++) {
351	        const a = ((x + 0.5) / N) * 2 - 1, b = ((y + 0.5) / N) * 2 - 1;
352	        radiance(faceDir(f, a, b).normalize(), col);
353	        const i = (y * N + x) * 4;
354	        data[i] = THREE.DataUtils.toHalfFloat(col.r);
355	        data[i + 1] = THREE.DataUtils.toHalfFloat(col.g);
356	        data[i + 2] = THREE.DataUtils.toHalfFloat(col.b);
357	        data[i + 3] = THREE.DataUtils.toHalfFloat(1);
358	      }
359	    }
360	    const t = new THREE.DataTexture(data, N, N, THREE.RGBAFormat, THREE.HalfFloatType);
361	    t.colorSpace = THREE.LinearSRGBColorSpace;
362	    t.needsUpdate = true;
363	    faces.push(t);
364	  }
365	  const cube = new THREE.CubeTexture(faces as unknown as HTMLImageElement[]);
366	  cube.type = THREE.HalfFloatType;
367	  cube.format = THREE.RGBAFormat;
368	  cube.colorSpace = THREE.LinearSRGBColorSpace;
369	  cube.minFilter = THREE.LinearFilter;
370	  cube.magFilter = THREE.LinearFilter;
371	  cube.generateMipmaps = false;
372	  cube.needsUpdate = true;
373	  tubeEnvs[variant] = cube;
374	  return cube;
375	}
