1	/**
2	 * Tunnel geometry generated from course-aligned "tube paths", so walls, rings and nozzles follow the
3	 * 04 slide, the 06 arch and the full 07 plunge with no seams.
4	 *  - courseTubePath:   tube centred on the course itself (chute, gold ring pipe)
5	 *  - straightTubePath: tube on a low-pass-filtered axis of the course (05–07): the tunnel stays
6	 *    straight with concentric rings converging to one vanishing point (refs 05/07) while the stream
7	 *    winds inside it. Radius/depth adapt so the floor always stays below the winding stream, and the
8	 *    axis converges exactly onto the course at both ends (04 pipe junction, 08 chamber inlet).
9	 */
10	import * as THREE from 'three';
11	import type { Course } from './course';
12	
13	export interface Frame { pos: THREE.Vector3; tan: THREE.Vector3; up: THREE.Vector3; right: THREE.Vector3 }
14	
15	export interface TubePath {
16	  frame(s: number): Frame;
17	  radius(s: number): number;
18	  /** distance from the water point on the axis down to the tube bottom */
19	  depth(s: number): number;
20	}
21	
22	export function courseTubePath(course: Course, radius: (s: number) => number, depth: number | ((s: number) => number) = 0.9): TubePath {
23	  return {
24	    frame: (s) => course.sample(s),
25	    radius,
26	    depth: typeof depth === 'number' ? () => depth : depth,
27	  };
28	}
29	
30	export function straightTubePath(
31	  course: Course,
32	  s0: number,
33	  s1: number,
34	  opts: { window: number; taper: number; baseRadius: (s: number) => number },
35	): TubePath {
36	  const ds = 0.5;
37	  const n = Math.ceil((s1 - s0) / ds) + 1;
38	  const S = (i: number) => Math.min(s1, s0 + i * ds);
39	  const axis: THREE.Vector3[] = [];
40	  const cp: THREE.Vector3[] = [];
41	  for (let i = 0; i < n; i++) cp.push(course.sample(S(i)).pos.clone());
42	  for (let i = 0; i < n; i++) {
43	    const s = S(i);
44	    const taper = THREE.MathUtils.smoothstep(s, s0, s0 + opts.taper) * (1 - THREE.MathUtils.smoothstep(s, s1 - opts.taper, s1));
45	    const W = opts.window * taper;
46	    const k = Math.round(W / ds);
47	    let x = 0, z = 0, wsum = 0;
48	    for (let j = i - k; j <= i + k; j++) {
49	      const jj = THREE.MathUtils.clamp(j, 0, n - 1);
50	      const w = k === 0 ? 1 : 1 - Math.abs(j - i) / (k + 1);
51	      x += cp[jj].x * w; z += cp[jj].z * w; wsum += w;
52	    }
53	    axis.push(new THREE.Vector3(x / wsum, cp[i].y, z / wsum));
54	  }
55	  // exact straight stretches (05 current): the axis is pulled onto the course's straight centre line
56	  // (foot of the perpendicular from the stream point), so the tunnel is truly straight — no yaw
57	  // wiggle, no roll — and the rings converge on one vanishing point. Blends in over 12 units after
58	  // the 04 junction; height/roll/radius/depth return to the 06 arch tube just past its foot (wRun),
59	  // the lateral position over the last ~20 units of the stretch (wXZ) so the hand-over to the
60	  // filtered 06 axis has no yaw kink and 06 itself is unchanged.
61	  const wRun = new Array<number>(n).fill(0);
62	  const wXZ = new Array<number>(n).fill(0);
63	  const runDepth = new Array<number>(n).fill(0);
64	  for (const r of course.straightAxes ?? []) {
65	    if (r.s1 <= s0 || r.s0 >= s1) continue;
66	    const ab = r.b.clone().sub(r.a);
67	    const ab2 = ab.lengthSq();
68	    for (let i = 0; i < n; i++) {
69	      const s = S(i);
70	      const wIn = THREE.MathUtils.smoothstep(s, r.s0, r.s0 + 12);
71	      const w = wIn * (1 - THREE.MathUtils.smoothstep(s, r.s1 - 6, r.s1 + 2));
72	      const wl = wIn * (1 - THREE.MathUtils.smoothstep(s, r.s1 - 18, r.s1 + 2));
73	      if (wl <= wXZ[i]) continue;
74	      wXZ[i] = wl;
75	      wRun[i] = w;
76	      runDepth[i] = r.floorDepth;
77	      const u = cp[i].clone().sub(r.a).dot(ab) / ab2;
78	      const onLine = r.a.clone().addScaledVector(ab, u);
79	      axis[i].x += (onLine.x - axis[i].x) * wl;
80	      axis[i].z += (onLine.z - axis[i].z) * wl;
81	      axis[i].y += (onLine.y - axis[i].y) * w;
82	    }
83	  }
84	  const WU = new THREE.Vector3(0, 1, 0);
85	  const frames: Frame[] = axis.map((p, i) => {
86	    const a = axis[Math.max(0, i - 2)], b = axis[Math.min(n - 1, i + 2)];
87	    const tan = b.clone().sub(a).normalize();
88	    const cu = course.sample(S(i)).up.clone().lerp(WU, wRun[i]); // no banking roll on straight stretches
89	    const up = cu.addScaledVector(tan, -cu.dot(tan)).normalize();
90	    const right = new THREE.Vector3().crossVectors(tan, up).normalize();
91	    return { pos: p, tan, up, right };
92	  });
93	  // radius/depth so the floor stays below the stream edges, dilated + smoothed for a steady tube
94	  const rawR: number[] = [], rawD: number[] = [], needR: number[] = [], needD: number[] = [];
95	  for (let i = 0; i < n; i++) {
96	    const s = S(i);
97	    const off = cp[i].clone().sub(frames[i].pos);
98	    const d = off.dot(frames[i].right);
99	    const X = Math.abs(d) + course.widthAt(s) / 2 + 0.25;
100	    const r = Math.max(opts.baseRadius(s), X + 0.7);
101	    rawR.push(r);
102	    rawD.push(Math.max(0.9, r - Math.sqrt(Math.max(0, r * r - X * X)) + 0.2));
103	    // straight stretches: also account for the stream's height above/below the (straight) axis point
104	    needR.push(X + 0.7);
105	    needD.push(r - Math.sqrt(Math.max(0, r * r - X * X)) + 0.2 - off.dot(frames[i].up));
106	  }
107	  const dilate = (arr: number[], k: number) => arr.map((_, i) => { let m = -Infinity; for (let j = i - k; j <= i + k; j++) m = Math.max(m, arr[THREE.MathUtils.clamp(j, 0, n - 1)]); return m; });
108	  const box = (arr: number[], k: number) => arr.map((_, i) => { let a = 0; for (let j = i - k; j <= i + k; j++) a += arr[THREE.MathUtils.clamp(j, 0, n - 1)]; return a / (2 * k + 1); });
109	  const R = box(dilate(rawR, 30), 16);
110	  const D = box(dilate(rawD, 30), 16);
111	  if (wRun.some((w) => w > 0)) {
112	    // on a straight stretch the tunnel keeps its own constant radius (the next stage's wider hall is
113	    // not dilated back into it) and the stream sits `floorDepth` above the tunnel bottom (wide current)
114	    const nR = box(dilate(needR, 30), 16);
115	    const nD = box(dilate(needD, 30), 16);
116	    for (let i = 0; i < n; i++) {
117	      const w = wRun[i];
118	      if (w <= 0) continue;
119	      R[i] += (Math.max(opts.baseRadius(S(i)), nR[i]) - R[i]) * w;
120	      D[i] += (Math.max(runDepth[i], nD[i], 0.9) - D[i]) * w;
121	    }
122	  }
123	  const idx = (s: number) => {
124	    const x = THREE.MathUtils.clamp((s - s0) / ds, 0, n - 1);
125	    const i = Math.min(n - 2, Math.floor(x));
126	    return { i, f: x - i };
127	  };
128	  const lerpArr = (arr: number[], s: number) => { const { i, f } = idx(s); return arr[i] + (arr[i + 1] - arr[i]) * f; };
129	  return {
130	    frame(s) {
131	      const { i, f } = idx(s);
132	      const A = frames[i], B = frames[i + 1];
133	      const pos = A.pos.clone().lerp(B.pos, f);
134	      const tan = A.tan.clone().lerp(B.tan, f).normalize();
135	      const up = A.up.clone().lerp(B.up, f);
136	      up.addScaledVector(tan, -up.dot(tan)).normalize();
137	      return { pos, tan, up, right: new THREE.Vector3().crossVectors(tan, up).normalize() };
138	    },
139	    radius: (s) => lerpArr(R, s),
140	    depth: (s) => lerpArr(D, s),
141	  };
142	}
143	
144	export function tubeCenterAt(path: TubePath, s: number, out = new THREE.Vector3()) {
145	  const f = path.frame(s);
146	  return out.copy(f.pos).addScaledVector(f.up, path.radius(s) - path.depth(s));
147	}
148	
149	export interface TubeGeoOptions {
150	  radial?: number;
151	  step?: number;
152	  vScale?: number;
153	  /** angular range (radians, measured from the bottom) — default full circle */
154	  arc?: number;
155	  /** radius offset (negative = inset toward the axis) */
156	  inset?: number;
157	  /**
158	   * Store the front-face (outward) normal. The faces wind outward, so BackSide/DoubleSide materials
159	   * flip this to the inward normal and light the inside of the tube correctly. The legacy default
160	   * (false) stores -d, which those materials flip to point AWAY from the viewer (dot(N,V) <= 0 →
161	   * full fresnel, un-tinted pale reflections); kept only so the 02 chute / 04 pipe look is unchanged.
162	   */
163	  frontNormals?: boolean;
164	  /** also store the local tube frame per vertex (`tubeAxis`, `tubeUp`) for withTubeStrips('attribute') */
165	  axisAttr?: boolean;
166	}
167	
168	export function buildTubeGeometry(path: TubePath, s0: number, s1: number, o: TubeGeoOptions = {}): THREE.BufferGeometry {
169	  const radial = o.radial ?? 48;
170	  const step = o.step ?? 0.6;
171	  const vScale = o.vScale ?? 1;
172	  const arc = o.arc ?? Math.PI * 2;
173	  const ns = o.frontNormals ? 1 : -1;
174	  const rings = Math.max(2, Math.ceil((s1 - s0) / step) + 1);
175	  const pos = new Float32Array(rings * (radial + 1) * 3);
176	  const nor = new Float32Array(rings * (radial + 1) * 3);
177	  const uv = new Float32Array(rings * (radial + 1) * 2);
178	  const ax = o.axisAttr ? new Float32Array(rings * (radial + 1) * 3) : null;
179	  const au = o.axisAttr ? new Float32Array(rings * (radial + 1) * 3) : null;
180	  const c = new THREE.Vector3();
181	  const d = new THREE.Vector3();
182	  for (let i = 0; i < rings; i++) {
183	    const s = s0 + ((s1 - s0) * i) / (rings - 1);
184	    const f = path.frame(s);
185	    const r = path.radius(s) + (o.inset ?? 0);
186	    c.copy(f.pos).addScaledVector(f.up, path.radius(s) - path.depth(s));
187	    for (let j = 0; j <= radial; j++) {
188	      const th = -Math.PI / 2 - arc / 2 + (j / radial) * arc; // centred on the bottom
189	      d.copy(f.right).multiplyScalar(Math.cos(th)).addScaledVector(f.up, Math.sin(th));
190	      const k = i * (radial + 1) + j;
191	      if (ax && au) { f.tan.toArray(ax, k * 3); f.up.toArray(au, k * 3); }
192	      pos[k * 3] = c.x + d.x * r;
193	      pos[k * 3 + 1] = c.y + d.y * r;
194	      pos[k * 3 + 2] = c.z + d.z * r;
195	      nor[k * 3] = ns * d.x; nor[k * 3 + 1] = ns * d.y; nor[k * 3 + 2] = ns * d.z;
196	      uv[k * 2] = j / radial;
197	      uv[k * 2 + 1] = s / vScale;
198	    }
199	  }
200	  const idx: number[] = [];
201	  for (let i = 0; i < rings - 1; i++) {
202	    for (let j = 0; j < radial; j++) {
203	      const a = i * (radial + 1) + j, b = a + radial + 1;
204	      idx.push(a, b, a + 1, b, b + 1, a + 1);
205	    }
206	  }
207	  const g = new THREE.BufferGeometry();
208	  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
209	  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
210	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
211	  if (ax && au) {
212	    g.setAttribute('tubeAxis', new THREE.BufferAttribute(ax, 3));
213	    g.setAttribute('tubeUp', new THREE.BufferAttribute(au, 3));
214	  }
215	  g.setIndex(idx);
216	  g.computeBoundingSphere();
217	  return g;
218	}
219	
220	/**
221	 * Washer-tube ring collar (ref 05: "flat gold band with a double contour"): a broad FLAT inner band that
222	 * barely stands off the wall, a dark groove, then a thin raised lip on the near edge (−z, the side the
223	 * rider looks at) whose small camera-facing side catches a bright line. The protrusion is shallow on
224	 * purpose: a deep collar shows a big camera-facing annulus (the old "thick orange pipe" look, 21% gold)
225	 * and pokes through the stream where it hugs the wall (06 arch).
226	 * Lathe around local Z; radial values are fractions of the tube radius, axial values are world units
227	 * (the instance scales z by 1). Interior corners are duplicated so every facet keeps a crisp normal.
228	 */
229	export function collarGeometry(depth = 0.022, lip = 0.012, width = 1.1, segments = 96): THREE.BufferGeometry {
230	  const w = width / 2;
231	  const d = depth;
232	  const lipW = Math.min(0.16, width * 0.15), groove = Math.min(0.07, width * 0.06);
233	  // traversed from +z to -z so LatheGeometry's faces/normals point INWARD (toward the tunnel axis)
234	  const prof: [number, number][] = [
235	    [1.03, w], [1 - d * 0.5, w], // far side (hidden from the rider)
236	    [1 - d, w - 0.05], // far chamfer
237	    [1 - d, -w + lipW + groove + 0.02], // the flat band
238	    [1 - d * 0.55, -w + lipW + groove * 0.5], // dark groove (recessed toward the wall)
239	    [1 - d - lip, -w + lipW], [1 - d - lip, -w + 0.05], // raised lip
240	    [1 - d * 0.35, -w], // lip's camera-facing side → thin bright contour
241	    [1.03, -w],
242	  ];
243	  const pts: THREE.Vector2[] = [];
244	  prof.forEach(([x, y], i) => {
245	    pts.push(new THREE.Vector2(x, y));
