/**
 * Shared image-based lighting for the candy-laundry look: a procedural "studio" of glowing
 * pink / magenta / gold / white panels baked into a PMREM environment once at load time.
 * Gold rings, chrome door, coins, star badges and glossy water all reflect it.
 */
import * as THREE from 'three';

export function createCandyEnvironment(renderer: THREE.WebGLRenderer): THREE.Texture {
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#a8338f');
  const box = new THREE.BoxGeometry(1, 1, 1);
  const panel = (color: string, intensity: number, pos: [number, number, number], scale: [number, number, number]) => {
    const m = new THREE.MeshBasicMaterial({ color: new THREE.Color(color).multiplyScalar(intensity), side: THREE.BackSide });
    const mesh = new THREE.Mesh(box, m);
    mesh.position.set(...pos);
    mesh.scale.set(...scale);
    scene.add(mesh);
  };
  // room shell (inside of a big box): magenta-violet
  const shell = new THREE.Mesh(new THREE.BoxGeometry(40, 30, 40), new THREE.MeshBasicMaterial({ color: '#7a2a9c', side: THREE.BackSide }));
  scene.add(shell);
  const p = (color: string, intensity: number, pos: [number, number, number], scale: [number, number, number]) => {
    const m = new THREE.MeshBasicMaterial({ color: new THREE.Color(color).multiplyScalar(intensity) });
    const mesh = new THREE.Mesh(box, m);
    mesh.position.set(...pos);
    mesh.scale.set(...scale);
    scene.add(mesh);
  };
  p('#ffffff', 6, [0, 14, 0], [18, 0.5, 18]); // big soft key from above
  p('#ffe08a', 5, [-19, 4, 0], [0.5, 14, 30]); // warm gold bounce left
  p('#ff5fd2', 3.5, [19, 2, 0], [0.5, 12, 26]); // hot pink right
  p('#6ff4ff', 2.6, [0, -2, -19], [24, 8, 0.5]); // cyan water glow from the front
  p('#ffffff', 5, [6, 6, 19], [6, 6, 0.5]); // small hard highlight behind camera
  p('#c76bff', 2, [0, -14, 0], [30, 0.5, 30]); // violet floor
  void panel;
  const pmrem = new THREE.PMREMGenerator(renderer);
  const rt = pmrem.fromScene(scene, 0.035);
  pmrem.dispose();
  scene.traverse((o) => {
    const m = o as THREE.Mesh;
    if (m.isMesh) (m.material as THREE.Material).dispose();
  });
  box.dispose();
  return rt.texture;
}

/** Standard renderer setup used by the game and the tools. */
export function createRenderer(canvas: HTMLCanvasElement, opts: { preserveDrawingBuffer?: boolean } = {}): THREE.WebGLRenderer {
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    alpha: false,
    powerPreference: 'high-performance',
    preserveDrawingBuffer: !!opts.preserveDrawingBuffer,
  });
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.NeutralToneMapping;
  renderer.toneMappingExposure = 0.86;
  return renderer;
}
/** Final colour grade (display space): saturation / contrast / gentle vignette for the candy look. */
import * as THREE from 'three';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';

export function createGradePass(opts: { saturation?: number; contrast?: number; vignette?: number } = {}) {
  return new ShaderPass({
    uniforms: {
      tDiffuse: { value: null },
      uSat: { value: opts.saturation ?? 1.36 },
      uCon: { value: opts.contrast ?? 1.15 },
      uVig: { value: opts.vignette ?? 0.18 },
    },
    vertexShader: /* glsl */ `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: /* glsl */ `
      uniform sampler2D tDiffuse; uniform float uSat; uniform float uCon; uniform float uVig; varying vec2 vUv;
      void main(){
        vec4 c = texture2D(tDiffuse, vUv);
        float l = dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
        vec3 col = mix(vec3(l), c.rgb, uSat);
        col = (col - 0.5) * uCon + 0.5;
        vec2 d = vUv - 0.5; d.x *= 0.75;
        col *= 1.0 - uVig * smoothstep(0.25, 0.75, length(d));
        gl_FragColor = vec4(clamp(col, 0.0, 1.0), c.a);
      }`,
  } as unknown as THREE.ShaderMaterialParameters);
}
#!/usr/bin/env node
// Playwright capture of the REAL running game (WebGL) at the native reference sizes.
//   node scripts/capture.mjs                 → screenshots/01.png … 11.png (+ qa/capture_log.json)
//   node scripts/capture.mjs 03 07           → only those
//   node scripts/capture.mjs --plunge        → qa/continuity/07a…07d.png descent proof frames
//   node scripts/capture.mjs --size=1080x1920 → extra Android-size set into screenshots/1080x1920/
//   node scripts/capture.mjs --out=DIR       → custom output dir
import { mkdirSync, writeFileSync } from 'node:fs';
import { loadPlaywright, CHROMIUM_ARGS, startVite } from './lib/pw.mjs';

const args = process.argv.slice(2);
const opt = Object.fromEntries(args.filter((a) => a.startsWith('--')).map((a) => { const [k, v] = a.slice(2).split('='); return [k, v ?? true]; }));
let ids = args.filter((a) => !a.startsWith('--'));
const NATIVE = { '03': [727, 1536] };
const plunge = ['07a_plunge_top', '07b_plunge_mid', '07c_plunge_bottom', '07d_entering_08'];
if (opt.plunge) ids = plunge;
if (!ids.length) ids = ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11'];
const size = typeof opt.size === 'string' ? opt.size.split('x').map(Number) : null;
const outDir = typeof opt.out === 'string' ? opt.out : opt.plunge ? 'qa/continuity' : size ? `screenshots/${size[0]}x${size[1]}` : 'screenshots';
mkdirSync(outDir, { recursive: true });
mkdirSync('qa', { recursive: true });

const { chromium } = loadPlaywright();
const vite = await startVite(5201);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = { when: new Date().toISOString(), renderer: null, shots: [], errors: [] };
try {
  for (const id of ids) {
    const [w, h] = size ?? NATIVE[id] ?? [864, 1536];
    const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
    page.on('console', (m) => { if (m.type() === 'error') log.errors.push(`[${id}] ${m.text()}`); });
    page.on('pageerror', (e) => log.errors.push(`[${id}] pageerror ${e.message}`));
    await page.goto(`${vite.url}/?qa=1&dpr=1${typeof opt.q === "string" ? "&" + opt.q : ""}`);
    await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 240000 });
    const err = await page.evaluate(() => window.__error);
    if (err) throw new Error(err);
    if (!log.renderer) log.renderer = await page.evaluate(() => { const g = document.querySelector('canvas').getContext('webgl2'); const d = g?.getExtension('WEBGL_debug_renderer_info'); return d ? g.getParameter(d.UNMASKED_RENDERER_WEBGL) : 'unknown'; });
    const st = await page.evaluate((cid) => window.__rainbow.goto(cid), id);
    // let a few frames render (fonts, bloom) — time is frozen so the image is deterministic
    await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r())));
    await page.evaluate(() => document.fonts.ready);
    await page.waitForTimeout(250);
    const name = /^\d\d$/.test(id) ? `${id}.png` : `${id}.png`;
    await page.screenshot({ path: `${outDir}/${name}`, timeout: 180000 });
    const stats = await page.evaluate(() => window.__rainbow.stats());
    const state = await page.evaluate(() => window.__rainbow.state());
    log.shots.push({ id, file: `${outDir}/${name}`, size: [w, h], checkpoint: st, state, stats });
    console.log(id, '→', `${outDir}/${name}`, JSON.stringify({ stage: state.stage, s: state.s, y: state.bennyY, calls: stats.calls, tris: stats.triangles, modules: stats.modules }));
    await page.close();
  }
} finally {
  writeFileSync(opt.plunge ? 'qa/continuity/capture_log.json' : `qa/capture_log${size ? '_' + size.join('x') : ''}.json`, JSON.stringify(log, null, 2));
  await browser.close();
  await vite.close();
}
if (log.errors.length) console.error('console errors:', log.errors.slice(0, 10));

