      const B = WORLD.basin;
      const wp = benny.clone().add(new THREE.Vector3(2.8, 3.6, 5.6));
      const drain = new THREE.Vector3(B.center.x, B.drainY, B.center.z);
      const wt = benny.clone().lerp(drain, 0.2).add(new THREE.Vector3(0.6, -1.0, -2.4));
