// offline projection of the 05 tunnel rings/lids for the 05 checkpoint camera (864x1536)
// run: cd /home/user/rainbow- && npx vite-node <this file> -- [spacing] [phase] [n]
import * as THREE from 'three';
import { Course } from '/home/user/rainbow-/src/world/course.ts';
import { straightTubePath, tubeCenterAt } from '/home/user/rainbow-/src/world/tube.ts';
import { RideCamera } from '/home/user/rainbow-/src/game/cameraRig.ts';

const argv = process.argv.slice(2).filter((a) => a !== '--');
const spacing = Number(argv[0] ?? 9);
const phase = Number(argv[1] ?? 7.8);
const course = new Course();
const s05 = course.stage('05').s0, s06 = course.stage('06').s0, s08 = course.stage('08').s0;
const perfPath = straightTubePath(course, s05, s08, { window: 30, taper: 14, baseRadius: (s) => course.prop('tube', s) });
const rc = new RideCamera(course);
rc.axis = { path: perfPath, s0: s05, s1: course.marks['07_plunge_top'] };
const cam = new THREE.PerspectiveCamera(66, 864 / 1536, 0.05, 1200);
const sB = course.marks['05_crest'];
rc.update(0, sB, 0, cam, true);
cam.updateMatrixWorld(); cam.updateProjectionMatrix();
const W = 864, H = 1536;
const px = (p: THREE.Vector3) => { const v = p.clone().project(cam); return [((v.x + 1) / 2) * W, ((1 - v.y) / 2) * H, v.z] as const; };
console.log('s05', s05.toFixed(2), 's06', s06.toFixed(2), 'sBenny', sB.toFixed(2), 'cam', cam.position.toArray().map((v) => v.toFixed(2)).join(','), 'fov', cam.fov);
// VP of the axis
const af = perfPath.frame(sB + 40);
const far = tubeCenterAt(perfPath, sB + 40).addScaledVector(af.tan, 1000);
console.log('axis VP', px(far).slice(0, 2).map((v) => v.toFixed(0)).join(','));
// camera axial position along the path: find s where (cam - centre)·tan = 0
let sCam = sB;
for (let it = 0; it < 30; it++) { const f = perfPath.frame(sCam); const c = tubeCenterAt(perfPath, sCam); sCam += cam.position.clone().sub(c).dot(f.tan) * 0.9; }
const cc = tubeCenterAt(perfPath, sCam); const cf = perfPath.frame(sCam);
console.log('camera s', sCam.toFixed(2), 'height above axis', cam.position.clone().sub(cc).dot(cf.up).toFixed(2), 'lat', cam.position.clone().sub(cc).dot(cf.right).toFixed(2), 'R', perfPath.radius(sCam).toFixed(2), 'depth', perfPath.depth(sCam).toFixed(2));
const inset = 0.02 + 0.022; // ring band inner radius ≈ r(1-depth)
const rows: string[] = [];
const s0r = s05 + phase;
for (let s = s0r; s < s06 + 12; s += spacing) {
  if (s < sCam - 1) continue;
  const f = perfPath.frame(s); const c = tubeCenterAt(perfPath, s); const r = (perfPath.radius(s) - 0.02) * (1 - 0.022);
  const top = px(c.clone().addScaledVector(f.up, r));
  const bot = px(c.clone().addScaledVector(f.up, -r));
  const L = px(c.clone().addScaledVector(f.right, -r));
  const R = px(c.clone().addScaledVector(f.right, r));
  const ctr = px(c);
  rows.push(`s=${s.toFixed(1)} dz=${(s - sCam).toFixed(1)} R=${perfPath.radius(s).toFixed(2)} top=${top[1].toFixed(0)} bot=${bot[1].toFixed(0)} L=${L[0].toFixed(0)},${L[1].toFixed(0)} R=${R[0].toFixed(0)},${R[1].toFixed(0)} ctr=${ctr[0].toFixed(0)},${ctr[1].toFixed(0)} z=${top[2].toFixed(3)}`);
}
console.log(rows.join('\n'));
// frame-corner test for the nearest ring: sample points around the ring and print those inside the frame
const sNear = s0r + Math.ceil((sCam - s0r) / spacing) * spacing;
{
  const f = perfPath.frame(sNear); const c = tubeCenterAt(perfPath, sNear); const r = (perfPath.radius(sNear) - 0.02) * (1 - 0.022);
  const pts: string[] = [];
  for (let a = 0; a < 360; a += 15) {
    const th = THREE.MathUtils.degToRad(a);
    const p = px(c.clone().addScaledVector(f.right, Math.cos(th) * r).addScaledVector(f.up, Math.sin(th) * r));
    pts.push(`${a}:${p[0].toFixed(0)},${p[1].toFixed(0)}${p[2] > 1 ? 'B' : ''}`);
  }
  console.log('near ring s', sNear.toFixed(2), 'dz', (sNear - sCam).toFixed(2), pts.join(' '));
}
// lids (angle 18 deg above horizontal on both walls, mid-bay)
for (const ang of [Number(argv[2] ?? 18)]) {
  const a = THREE.MathUtils.degToRad(ang);
  const out: string[] = [];
  for (let s = s0r + spacing * 0.5; s < s06; s += spacing) {
    if (s < sCam) continue;
    const f = perfPath.frame(s); const c = tubeCenterAt(perfPath, s); const r = perfPath.radius(s) * 0.92;
    const l = px(c.clone().addScaledVector(f.right, -Math.cos(a) * r).addScaledVector(f.up, Math.sin(a) * r));
    const rr = px(c.clone().addScaledVector(f.right, Math.cos(a) * r).addScaledVector(f.up, Math.sin(a) * r));
    out.push(`dz${(s - sCam).toFixed(0)} L(${l[0].toFixed(0)},${l[1].toFixed(0)}) R(${rr[0].toFixed(0)},${rr[1].toFixed(0)})`);
  }
  console.log('lids @' + ang + 'deg:', out.join('  '));
}
// water-line height: stream y relative to axis at Benny
const fb = course.sample(sB);
console.log('stream at Benny: height above axis', fb.pos.clone().sub(tubeCenterAt(perfPath, sB)).dot(perfPath.frame(sB).up).toFixed(2));

